  loadError:'Could not open local storage. Check browser permissions and available space.',storageError:'Could not save data. Previous records were not overwritten. Please try again.',quota:'This browser has insufficient storage space. Latest changes are not saved.',conflict:'Data changed in another tab. Your saved records were not overwritten. Copy unsaved input before reloading.',importError:'Could not read this backup. Existing records are unchanged.',working:'Saving…',noText:'No text provided',detail:'Intention',emotionValues:['Love / affection','Joy / excitement','Hope / positive anticipation','Calm / contentment','Fear / anxiety','Anger / frustration','Sadness / disappointment','Shame / guilt','Neutral / little emotion','Other'],
