const FIELDS=['primary','success','scope','nonGoals','constraints','rationale'];
const EMOTIONS=['Love / affection','Joy / excitement','Hope / positive anticipation','Calm / contentment','Fear / anxiety','Anger / frustration','Sadness / disappointment','Shame / guilt','Neutral / little emotion','Other'];
const FREQUENCIES=['freq0','freq1','freq2','freq3','freq4','freq5'];
const DIRECTIONS=['toward','none','away','mixed','unknown'];
const EVIDENCE=['direct','documented','otherPerson','subjective','insufficient','other'];
const IEP_NUM=['desire','belief','emotionIntensity','mental','practical','hours'];
let lang='ru';try{lang=localStorage.getItem('pheisi_preview_language')==='en'?'en':'ru';}catch{}
let store, rows=[], drafts=new Map(), selected=null, session=null, screen='home', busy=false, errorText='', toast='', risInput=Object.fromEntries(FIELDS.map(k=>[k,'']));
let risOperationId=null;
const app=document.getElementById('app');
const t=k=>(lang==='ru'?RU:EN)[k]??k;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=value=>structuredClone(value);
const uid=()=>crypto.randomUUID();
const iconHome='<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/></svg>';
const iconData='<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>';
function formatDate(value){try{return new Intl.DateTimeFormat(lang==='ru'?'ru-RU':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}catch{return '';}}
function bodyOf(row){return row.sourceEnvelope.intent;}
function errorMessage(e,importing=false){const code=e?.code||'';if(code.includes('QUOTA'))return t('quota');if(code.includes('CONFLICT'))return t('conflict');return importing?t('importError'):t('storageError');}
function showError(message){errorText=message;let host=document.getElementById('errorBanner');if(!host){host=document.createElement('div');host.id='errorBanner';host.className='error-banner';host.setAttribute('role','alert');document.querySelector('.preview-strip')?.after(host);}host.textContent=message;}
function clearError(){errorText='';document.getElementById('errorBanner')?.remove();}
function setBusy(value){busy=value;document.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=value);}
function saveStatus(){const el=document.getElementById('saveStatus');if(!el||!session)return;const failed=session.lastError;const pending=session.savedVersion<session.version;el.className='save-line'+(failed?' error':pending?' saving':'');el.textContent=t(failed?'unsaved':pending?'saving':'saved');}
function header(){return '<header class="topbar"><span class="brand">PHEISI<span class="brand-dot"></span></span><div class="top-actions"><span class="preview-badge">'+(lang==='ru'?'Тестовая версия':'Preview')+'</span><button class="language" id="langToggle" aria-label="'+(lang==='ru'?'Переключить на английский':'Switch to Russian')+'">'+(lang==='ru'?'EN':'RU')+'</button></div></header><div class="preview-strip">'+t('preview')+'</div>';}
function nav(){return '<nav class="bottomnav" aria-label="'+t('home')+'"><button id="navHome" class="nav-item '+(screen==='data'?'':'active')+'">'+iconHome+t('home')+'</button><button id="navData" class="nav-item '+(screen==='data'?'active':'')+'">'+iconData+t('data')+'</button></nav>';}
function summaryRIS(ris){return '<div class="summary-list">'+FIELDS.map(k=>'<div class="summary-row"><div class="summary-key">'+t(k)+'</div><div class="summary-value" dir="auto">'+esc(ris[k])+'</div></div>').join('')+'</div>';}
function render(){document.title=lang==='ru'?'PHEISI · Тестовая версия':'PHEISI · Preview';document.documentElement.lang=lang;app.innerHTML=header()+(errorText?'<div id="errorBanner" class="error-banner" role="alert">'+esc(errorText)+'</div>':'')+'<main id="main">'+(toast?'<div class="success-toast" role="status">'+esc(toast)+'</div>':'')+({home:homeView,ris:risView,detail:detailView,observation:observationView,data:dataView}[screen]||homeView)()+'</main>'+nav();bind();saveStatus();}
function focusHeading(){const h=document.querySelector('main h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});}
async function refresh(){rows=await store.listIntentions();drafts=new Map(await Promise.all(rows.map(async row=>[row.intentKey,await store.readDraft(row.intentKey)])));}
function homeView(){return '<div class="page-intro"><div><p class="eyebrow">'+t('local')+'</p><h1>'+t('my')+'</h1><p class="lead">'+t('lead')+'</p></div>'+(rows.length?'<button id="addIntention" class="btn primary"><span class="plus" aria-hidden="true">+</span>'+t('add')+'</button>':'')+'</div>'+(rows.length?'<div class="intent-grid">'+rows.map(row=>{const intent=bodyOf(row),c=intent.cycles||[],d=drafts.get(row.intentKey);return '<article class="card intent-card" data-intent-key="'+esc(row.intentKey)+'"><h2 dir="auto">'+esc(intent.ris.primary)+'</h2><p class="intent-success" dir="auto">'+esc(intent.ris.success)+'</p><div class="intent-meta"><span>'+t('observations')+': '+c.length+'</span><span class="small-dot"></span><span>'+formatDate(row.updatedAt||intent.createdAt)+'</span></div><div class="intent-bottom"><span class="tag '+(d?'draft':'')+'">'+t(d?'draft':c.length?'progress':'notYet')+'</span><button class="open-intent" data-action="open" data-key="'+esc(row.intentKey)+'">'+t(d?'resume':'open')+' <span aria-hidden="true">↗</span></button></div></article>';}).join('')+'</div>':'<section class="card empty"><div class="seed" aria-hidden="true">❧</div><h2>'+t('emptyTitle')+'</h2><p>'+t('emptyText')+'</p><button id="addIntention" class="btn primary"><span class="plus" aria-hidden="true">+</span>'+t('emptyButton')+'</button></section>')+'<p class="quiet-note">'+t('analytics')+'</p>';}
function risView(){return '<div class="form-shell"><button class="back-link" id="backHome">← '+t('cancel')+'</button><div class="form-header"><p class="eyebrow">RIS · '+t('risTitle')+'</p><h1>'+t('newIntent')+'</h1><p class="lead">'+t('risLead')+'</p></div><form id="risForm" novalidate><div class="card form-card">'+FIELDS.map(k=>'<div class="field"><label class="field-label" for="ris-'+k+'">'+t(k)+'</label><textarea id="ris-'+k+'" data-ris="'+k+'" required aria-describedby="example-'+k+'" dir="auto">'+esc(risInput[k])+'</textarea><p class="example" id="example-'+k+'">'+t('example')+': '+t(k+'Example')+'</p></div>').join('')+'</div><div class="form-actions"><button type="button" class="btn secondary" id="risLater">'+t('later')+'</button><button type="submit" class="btn primary" id="risContinue">'+t('continue')+' →</button></div></form></div>';}
function detailView(){if(!selected)return '';const intent=bodyOf(selected),c=intent.cycles||[],d=drafts.get(selected.intentKey);return '<button class="back-link" id="backHome">← '+t('home')+'</button><div class="detail-hero"><p class="eyebrow">'+t('detail')+'</p><h1 dir="auto">'+esc(intent.ris.primary)+'</h1><p class="lead" dir="auto">'+esc(intent.ris.success)+'</p></div><div class="detail-grid"><section class="card"><h2>'+t('risTitle')+'</h2>'+summaryRIS(intent.ris)+'</section><section class="card detail-actions"><p class="eyebrow">'+t(d?'draft':c.length?'progress':'first')+'</p><h2>'+t(d?'resume':c.length?'newUpdate':'first')+'</h2><p>'+t(d?'resumeText':c.length?'updateText':'continueText')+'</p><button class="btn primary wide" id="'+(d||!c.length?'resumeObservation':'newObservation')+'">'+t(d?'resume':c.length?'newUpdate':'continue')+' →</button></section></div><section class="history"><div class="section-heading"><h2>'+t('history')+'</h2><span class="count-chip">'+c.length+'</span></div>'+(c.length?[...c].reverse().map(x=>'<article class="history-item"><div class="history-date">'+formatDate(x.createdAt)+'</div><h3>'+t('oop')+'</h3><div class="history-metrics"><span class="metric-pill">'+t('achievement')+' '+esc(x.oop.achievement)+'/10</span><span class="metric-pill">'+t('practical')+' '+esc(x.iep.practical)+'/10</span><span class="metric-pill">'+t('hours')+' '+esc(x.iep.hours)+'</span></div>'+(x.oop.currentState?'<p dir="auto">'+esc(x.oop.currentState)+'</p>':'')+(x.oop.events?'<p dir="auto">'+esc(x.oop.events)+'</p>':'')+'</article>').join(''):'<p class="lead">'+t('noHistory')+'</p>')+'</section><div class="analytics-note">'+t('analytics')+'</div>';}
function numberField(key,path,value,max=10,unit='scale'){return '<div class="field number-field"><label class="field-label" for="'+key+'">'+t(key)+'</label><div class="number-wrap"><input type="number" id="'+key+'" data-path="'+path+'" data-number="true" value="'+(value===null||value===undefined?'':esc(value))+'" min="0" max="'+max+'" step="'+(key==='hours'?'0.25':'1')+'" inputmode="decimal" placeholder="—" required aria-describedby="'+key+'-unit"><span class="number-unit" id="'+key+'-unit">'+t(unit)+'</span></div></div>';}
function options(values,labels,selectedValue){return '<option value="">'+t('choose')+'</option>'+values.map((value,i)=>'<option value="'+esc(value)+'"'+(value===selectedValue?' selected':'')+'>'+esc(labels[i])+'</option>').join('');}
function textField(key,path,value){return '<div class="field"><label class="field-label" for="'+key+'">'+t(key)+' <span class="optional">'+t('optional')+'</span></label><textarea id="'+key+'" data-path="'+path+'" dir="auto">'+esc(value)+'</textarea></div>';}
function iepView(){const v=session.values;return (session.kind==='progress'?'<div class="notice"><p>'+t('cieHint')+'</p><details><summary>'+t('risTitle')+'</summary>'+summaryRIS(v.cie)+'</details><label class="choice"><input type="checkbox" id="cieConfirm" '+(v.answered.cie?'checked':'')+'>'+t('cieConfirm')+'</label></div>':'')+'<div class="card form-card"><div class="number-grid">'+['desire','belief'].map(k=>numberField(k,'iep.'+k,v.iep[k])).join('')+'</div><div class="form-divider"></div><div class="field"><label class="field-label" for="emotion">'+t('emotion')+'</label><select id="emotion" data-path="iep.emotion" required>'+options(EMOTIONS,t('emotionValues'),v.iep.emotion)+'</select></div><div class="number-grid">'+['emotionIntensity','mental','practical'].map(k=>numberField(k,'iep.'+k,v.iep[k])).join('')+numberField('hours','iep.hours',v.iep.hours,168,'hoursUnit')+'</div><div class="form-divider"></div><div class="field"><label class="field-label" for="frequency">'+t('frequency')+'</label><select id="frequency" data-path="iep.frequency" required>'+options(FREQUENCIES,t('frequencyValues'),v.iep.frequency)+'</select></div>'+textField('actions','iep.actions',v.iep.actions)+'</div>';}
function oopView(){const v=session.values;return '<div class="card form-card">'+textField('currentState','oop.currentState',v.oop.currentState)+numberField('achievement','oop.achievement',v.oop.achievement)+'<div class="form-divider"></div>'+textField('events','oop.events',v.oop.events)+'<div class="field"><label class="field-label" for="direction">'+t('direction')+'</label><select id="direction" data-path="oop.direction" required>'+options(DIRECTIONS,t('directionValues'),v.oop.direction)+'</select></div><fieldset class="choice-list"><legend class="field-label">'+t('evidence')+'</legend>'+EVIDENCE.map((k,i)=>'<label class="choice"><input type="checkbox" name="evidence" value="'+k+'" '+(v.oop.evidence.includes(k)?'checked':'')+'>'+esc(t('evidenceValues')[i])+'</label>').join('')+'</fieldset>'+textField('external','oop.external',v.oop.external)+'</div>';}
function reviewView(){const v=session.values;return '<div class="card form-card"><h2 dir="auto">'+esc(v.cie.primary)+'</h2><div class="review-grid">'+[['desire',v.iep.desire+'/10'],['practical',v.iep.practical+'/10'],['hours',v.iep.hours],['achievement',v.oop.achievement+'/10']].map(([k,value])=>'<div class="review-item"><span>'+t(k)+'</span><strong>'+esc(value)+'</strong></div>').join('')+'</div>'+(v.oop.currentState?'<div class="notice" dir="auto">'+esc(v.oop.currentState)+'</div>':'')+'<div class="field"><label class="field-label" for="intentional">'+t('intentional')+'</label><select id="intentional" required>'+options(['no','yes','unsure'],[t('no'),t('yes'),t('unsure')],v.intentional)+'</select></div>'+(v.intentional==='yes'?'<p class="notice amber">'+t('revisionHint')+'</p>'+FIELDS.map(k=>'<div class="field"><label class="field-label" for="revision-'+k+'">'+t(k)+'</label><textarea id="revision-'+k+'" data-revision="'+k+'" dir="auto">'+esc(v.revision[k]||'')+'</textarea></div>').join(''):'')+'</div>';}
function observationView(){if(!session)return '';const n=session.step;const titles=['iepTitle','oopTitle','reviewTitle'],leads=['iepLead','oopLead','reviewLead'];return '<div class="form-shell"><button class="back-link" id="closeObservation">← '+t('later')+'</button><div class="stepper" aria-label="'+t('step')+' '+n+' '+t('of')+' 3">'+[1,2,3].map(i=>'<span class="step-segment '+(i<=n?'on':'')+'"></span>').join('')+'</div><div class="form-header"><p class="step-label">'+t('step')+' '+n+' '+t('of')+' 3 · '+t(n===1?'iep':n===2?'oop':'review')+'</p><h1>'+t(titles[n-1])+'</h1><p class="lead">'+t(leads[n-1])+'</p><div id="saveStatus" class="save-line" role="status" aria-live="polite"></div></div><form id="observationForm" novalidate>'+(n===1?iepView():n===2?oopView():reviewView())+'<div class="form-actions">'+(n>1?'<button type="button" class="btn secondary" id="backStep">← '+t('back')+'</button>':'')+'<button type="button" class="btn secondary" id="saveLater">'+t('later')+'</button><button type="submit" class="btn primary" id="'+(n===3?'completeObservation':'nextStep')+'">'+t(n===3?'complete':'next')+(n<3?' →':'')+'</button></div></form></div>';}
function dataView(){return '<div class="form-shell"><div class="form-header"><p class="eyebrow">PHEISI · Preview</p><h1>'+t('dataTitle')+'</h1><p class="lead">'+t('dataLead')+'</p></div><div class="data-stack"><section class="card data-card"><h2>'+t('backupTitle')+'</h2><p>'+t('backupText')+'</p><div class="form-actions"><button class="btn primary" id="exportBackup">'+t('export')+'</button><button class="btn secondary" id="chooseBackup">'+t('import')+'</button></div><input id="importBackup" class="file-input" type="file" accept=".json,application/json"><div id="importStatus" class="save-line" role="status" aria-live="polite" data-state="idle"></div><details><summary>'+t('legacy')+'</summary><p>'+t('legacyText')+'</p><button class="btn secondary" id="chooseLegacy">'+t('legacyButton')+'</button><input id="importLegacy" class="file-input" type="file" accept=".json,application/json"></details></section><section class="card data-card"><h2>'+t('privacyTitle')+'</h2><p>'+t('privacyText')+'</p><span class="preview-languages">'+t('languageLimit')+'</span></section></div></div>';}
function newValues(row){return {cie:clone(bodyOf(row).ris),iep:{desire:null,belief:null,emotion:'',emotionIntensity:null,mental:null,practical:null,hours:null,frequency:'',actions:''},oop:{currentState:'',achievement:null,events:'',direction:'',evidence:[],external:''},intentional:'',revision:{},answered:{cie:(bodyOf(row).cycles||[]).length===0}};}
function createSession(row,draft){const values=draft?clone(draft.values):newValues(row);values.answered??={};return {intentKey:row.intentKey,intentRevision:row.revision,draftRevision:draft?.revision??null,kind:draft?.kind??((bodyOf(row).cycles||[]).length?'progress':'first'),step:Math.max(1,Math.min(3,draft?.step||1)),values,version:draft?0:1,savedVersion:0,enqueuedVersion:0,tail:Promise.resolve(),timer:null,lastError:null,completeOperationId:uid()};}
function enqueueSave(ctx,force=false){if(ctx!==session)return ctx.tail;if(!force&&ctx.version<=ctx.enqueuedVersion)return ctx.tail;const version=ctx.version,snapshot=clone(ctx.values),step=ctx.step;ctx.enqueuedVersion=version;const operationId=uid();ctx.tail=ctx.tail.catch(()=>{}).then(async()=>{saveStatus();try{const result=await store.saveObservationDraft({operationId,intentKey:ctx.intentKey,expectedIntentRevision:ctx.intentRevision,expectedDraftRevision:ctx.draftRevision,draft:{kind:ctx.kind,step,values:snapshot}});ctx.draftRevision=result.draftRevision;ctx.savedVersion=version;ctx.lastError=null;if(ctx===session)clearError();}catch(e){ctx.lastError=e;if(ctx===session)showError(errorMessage(e));throw e;}finally{if(ctx===session)saveStatus();}});ctx.tail.catch(()=>{});return ctx.tail;}
function changed(){if(!session)return;session.version++;clearTimeout(session.timer);const ctx=session;ctx.timer=setTimeout(()=>{ctx.timer=null;enqueueSave(ctx).catch(()=>{});},350);saveStatus();}
async function flush(){if(!session)return;const ctx=session;clearTimeout(ctx.timer);ctx.timer=null;if(ctx.version>ctx.enqueuedVersion||ctx.lastError)enqueueSave(ctx,!!ctx.lastError);await ctx.tail;if(ctx.lastError)throw ctx.lastError;}
async function go(target){
  if(busy)return;setBusy(true);
  try{await flush();await refresh();session=null;clearError();toast='';screen=target;render();focusHeading();}
  catch(e){showError(errorMessage(e));}finally{setBusy(false);}
}
async function openDetail(key){
  if(busy)return;setBusy(true);
  try{await flush();const row=await store.readIntention(key);await refresh();session=null;selected=row;clearError();toast='';screen='detail';render();focusHeading();}
  catch(e){showError(errorMessage(e));}finally{setBusy(false);}
}
async function beginObservation(){
  if(busy)return;setBusy(true);
  try{clearError();const saved=await store.readDraft(selected.intentKey);session=createSession(selected,saved);if(!saved)await enqueueSave(session);screen='observation';toast='';render();focusHeading();}
  catch(e){session=null;showError(errorMessage(e));}finally{setBusy(false);}
}
async function saveRIS(later){
  if(busy)return;
  const first=FIELDS.find(k=>!risInput[k].trim());
  if(first){showError(t('allRequired'));document.getElementById('ris-'+first)?.focus();return;}
  risOperationId??=uid();let createdKey=null;setBusy(true);
  try{
    const result=await store.addIntention({operationId:risOperationId,ris:clone(risInput)});
    createdKey=result.intentKey;selected=await store.readIntention(createdKey);
    const existingDraft=await store.readDraft(createdKey);session=createSession(selected,existingDraft);
    if(!existingDraft)await enqueueSave(session);
    await refresh();clearError();toast='';
    if(later){session=null;screen='detail';}else screen='observation';render();focusHeading();
  }catch(e){
    if(createdKey){try{const saved=await store.readIntention(createdKey);await refresh();selected=saved;session=null;screen='detail';render();focusHeading();}catch{}}
    showError(errorMessage(e));
  }finally{setBusy(false);}
}
function validateStep(){const v=session.values;if(session.step===1){if(session.kind==='progress'&&v.answered.cie!==true)return ['cieRequired','cieConfirm'];for(const k of IEP_NUM){const value=v.iep[k];if(!v.answered['iep.'+k]||!Number.isFinite(value)||value<0||value>(k==='hours'?168:10))return ['requiredAnswers',k];}if(!EMOTIONS.includes(v.iep.emotion))return ['requiredAnswers','emotion'];if(!FREQUENCIES.includes(v.iep.frequency))return ['requiredAnswers','frequency'];}if(session.step===2){if(!v.answered['oop.achievement']||!Number.isFinite(v.oop.achievement)||v.oop.achievement<0||v.oop.achievement>10)return ['requiredAnswers','achievement'];if(!DIRECTIONS.includes(v.oop.direction))return ['requiredAnswers','direction'];if(!v.oop.evidence.length)return ['evidenceRequired',null];}if(session.step===3){if(!['yes','no','unsure'].includes(v.intentional))return ['intentionalRequired','intentional'];if(v.intentional==='yes'&&!Object.values(v.revision).some(x=>typeof x==='string'&&x.trim()))return ['revisionRequired','revision-primary'];}return null;}
async function moveStep(delta){
  if(busy||!session)return;
  if(delta>0){const invalid=validateStep();if(invalid){showError(t(invalid[0]));document.getElementById(invalid[1])?.focus();return;}}
  const ctx=session,previous=ctx.step,target=previous+delta;if(target<1||target>3)return;setBusy(true);
  try{await flush();ctx.step=target;ctx.version++;await enqueueSave(ctx);clearError();render();focusHeading();}
  catch(e){if(ctx===session&&ctx.step!==previous){ctx.step=previous;ctx.version++;}showError(errorMessage(e));}
  finally{setBusy(false);}
}
async function complete(){const invalid=validateStep();if(invalid){showError(t(invalid[0]));document.getElementById(invalid[1])?.focus();return;}setBusy(true);try{await flush();const ctx=session;await store.completeObservation({operationId:ctx.completeOperationId,intentKey:ctx.intentKey,expectedIntentRevision:ctx.intentRevision,expectedDraftRevision:ctx.draftRevision});selected=await store.readIntention(ctx.intentKey);session=null;await refresh();clearError();toast=t('savedObservation');screen='detail';render();focusHeading();}catch(e){showError(errorMessage(e));}finally{setBusy(false);}}
async function saveAndClose(){
  if(busy)return;setBusy(true);
  try{await flush();const key=session?.intentKey;const row=key?await store.readIntention(key):selected;await refresh();session=null;selected=row;screen='detail';clearError();render();focusHeading();}
  catch(e){showError(errorMessage(e));}finally{setBusy(false);}
}
function setPath(path,value){const [group,key]=path.split('.');session.values[group][key]=value;}
function bind(){document.getElementById('langToggle')?.addEventListener('click',async()=>{if(busy)return;try{await flush();lang=lang==='ru'?'en':'ru';try{localStorage.setItem('pheisi_preview_language',lang);}catch{}errorText='';toast='';render();}catch(e){showError(errorMessage(e));}});document.getElementById('navHome')?.addEventListener('click',()=>go('home'));document.getElementById('navData')?.addEventListener('click',()=>go('data'));document.getElementById('backHome')?.addEventListener('click',()=>go('home'));document.getElementById('addIntention')?.addEventListener('click',()=>{risOperationId=uid();risInput=Object.fromEntries(FIELDS.map(k=>[k,'']));clearError();toast='';screen='ris';render();focusHeading();});document.querySelectorAll('[data-action="open"]').forEach(el=>el.addEventListener('click',()=>openDetail(el.dataset.key)));document.querySelectorAll('[data-ris]').forEach(el=>el.addEventListener('input',()=>{risInput[el.dataset.ris]=el.value;}));document.getElementById('risForm')?.addEventListener('submit',e=>{e.preventDefault();saveRIS(false);});document.getElementById('risLater')?.addEventListener('click',()=>saveRIS(true));document.getElementById('resumeObservation')?.addEventListener('click',beginObservation);document.getElementById('newObservation')?.addEventListener('click',beginObservation);
document.querySelectorAll('[data-path]').forEach(el=>{const capture=()=>{if(!session)return;let value=el.value;if(el.dataset.number){value=value.trim()===''?null:Number(value);setPath(el.dataset.path,value);session.values.answered[el.dataset.path]=Number.isFinite(value);}else setPath(el.dataset.path,value);changed();};el.addEventListener(el.tagName==='SELECT'?'change':'input',capture);});document.querySelectorAll('[name=evidence]').forEach(el=>el.addEventListener('change',()=>{session.values.oop.evidence=[...document.querySelectorAll('[name=evidence]:checked')].map(x=>x.value);changed();}));document.getElementById('cieConfirm')?.addEventListener('change',e=>{session.values.answered.cie=e.target.checked;changed();});document.getElementById('intentional')?.addEventListener('change',e=>{session.values.intentional=e.target.value;if(e.target.value!=='yes')session.values.revision={};changed();render();document.getElementById('intentional')?.focus();});document.querySelectorAll('[data-revision]').forEach(el=>el.addEventListener('input',()=>{if(el.value.trim())session.values.revision[el.dataset.revision]=el.value;else delete session.values.revision[el.dataset.revision];changed();}));document.getElementById('observationForm')?.addEventListener('submit',e=>{e.preventDefault();session.step===3?complete():moveStep(1);});document.getElementById('backStep')?.addEventListener('click',()=>moveStep(-1));document.getElementById('saveLater')?.addEventListener('click',saveAndClose);document.getElementById('closeObservation')?.addEventListener('click',saveAndClose);document.getElementById('exportBackup')?.addEventListener('click',exportBackup);document.getElementById('chooseBackup')?.addEventListener('click',()=>document.getElementById('importBackup').click());document.getElementById('chooseLegacy')?.addEventListener('click',()=>document.getElementById('importLegacy').click());document.getElementById('importBackup')?.addEventListener('change',e=>importBackup(e,false));document.getElementById('importLegacy')?.addEventListener('change',e=>importBackup(e,true));}
async function exportBackup(){setBusy(true);try{const text=await store.exportFile();const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='PHEISI-preview-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);clearError();}catch(e){showError(errorMessage(e));}finally{setBusy(false);}}
async function importBackup(event,legacy){
 if(busy)return;const file=event.target.files?.[0];if(!file)return;
 let committed=false;setBusy(true);importStatus('pending',t('working'));
 try{
  const text=await file.text();
  if(legacy)await store.importLegacy({operationId:uid(),rawState:text});
  else await store.importFile({operationId:uid(),text});
  committed=true;await refresh();clearError();toast=t('imported');render();importStatus('success',t('imported'));
 }catch(e){const message=errorMessage(e,!committed);showError(message);importStatus('error',message);}
 finally{setBusy(false);event.target.value='';}
}
function importStatus(state,message){const el=document.getElementById('importStatus');if(!el)return;el.dataset.state=state;el.textContent=message;el.className='save-line'+(state==='error'?' error':'');el.setAttribute('role',state==='error'?'alert':'status');}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&session){clearTimeout(session.timer);session.timer=null;enqueueSave(session).catch(()=>{});}});
try{store=await openPreviewStore();await refresh();render();}catch(e){errorText=t('loadError');render();document.querySelectorAll('main button').forEach(el=>el.disabled=true);}
